            8 => Reinterpret<long, nuint>( Math.Min(Math.Max(Reinterpret<nuint, long>(value), Reinterpret<nuint, long>(min)), Reinterpret<nuint, long>(max)) ),
            _ => throw new NotSupportedException(),
        };

    public static partial nint   Clamp(nint   value, nint   min, nint   max)
        => IntPtr.Size switch
        {
            4 => Reinterpret<int , nint>( Math.Min(Math.Max(Reinterpret<nint, int >(value), Reinterpret<nint, int >(min)), Reinterpret<nint, int >(max)) ),
            8 => Reinterpret<long, nint>( Math.Min(Math.Max(Reinterpret<nint, long>(value), Reinterpret<nint, long>(min)), Reinterpret<nint, long>(max)) ),
            _ => throw new NotSupportedException(),
        };
        
#endif

